import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"CLI Tools Reference","description":"","frontmatter":{},"headers":[],"relativePath":"publishing/cli-tools.md","filePath":"publishing/cli-tools.md","lastUpdated":1795110344000}'),s={name:"publishing/cli-tools.md"};function d(l,e,n,c,r,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="cli-tools-reference" tabindex="-1">CLI Tools Reference <a class="header-anchor" href="#cli-tools-reference" aria-label="Permalink to &quot;CLI Tools Reference&quot;">​</a></h1><p><code>jetpack-daemon</code> ships with built-in developer, packaging, catalog signing, and diagnostic subcommands (<code>crates/jetpack-daemon/src/main.rs</code> and <code>dev_cli.rs</code>).</p><h2 id="developer-publisher-commands" tabindex="-1">Developer &amp; Publisher Commands <a class="header-anchor" href="#developer-publisher-commands" aria-label="Permalink to &quot;Developer &amp; Publisher Commands&quot;">​</a></h2><h3 id="init-app-target-dir" tabindex="-1"><code>--init-app &lt;target_dir&gt;</code> <a class="header-anchor" href="#init-app-target-dir" aria-label="Permalink to &quot;`--init-app &lt;target_dir&gt;`&quot;">​</a></h3><p>Scaffolds a ready-to-run starter Python worker project in <code>&lt;target_dir&gt;</code> (refuses to overwrite an existing <code>app.toml</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker</span></span></code></pre></div><p>Creates:</p><ul><li><code>app.toml</code> — Validated starter manifest using a non-official <code>com.dev.&lt;slug&gt;</code> ID (<code>com.dev.my-ocr-worker</code>).</li><li><code>worker.py</code> — Executable (<code>0755</code> on Unix) Python worker using <code>jetpack_sdk.JetPackClient</code>.</li><li><code>pyproject.toml</code> — Project metadata (<code>requires-python = &quot;&gt;=3.12&quot;</code>, <code>jetpack-sdk</code> dependency).</li><li><code>README.md</code> — Project-specific validation, local install, and packaging commands.</li></ul><h3 id="validate-manifest-path" tabindex="-1"><code>--validate-manifest &lt;path&gt;</code> <a class="header-anchor" href="#validate-manifest-path" aria-label="Permalink to &quot;`--validate-manifest &lt;path&gt;`&quot;">​</a></h3><p>Parses an <code>app.toml</code> file with <code>#[serde(deny_unknown_fields)]</code> and runs all semantic and security checks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --validate-manifest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker/app.toml</span></span></code></pre></div><h3 id="install-local-app-source-dir" tabindex="-1"><code>--install-local-app &lt;source_dir&gt;</code> <a class="header-anchor" href="#install-local-app-source-dir" aria-label="Permalink to &quot;`--install-local-app &lt;source_dir&gt;`&quot;">​</a></h3><p>Validates, packages, and installs a local developer worker directly into <code>&lt;root&gt;/blobs/sha256/</code> and <code>&lt;root&gt;/apps/&lt;app-id&gt;/&lt;version&gt;/</code> in unverified developer mode (<code>is_verified = false</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-local-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker</span></span></code></pre></div><ul><li>Blocks official <code>SignedAppCatalog</code> IDs (<code>APP_SPOOFING_DETECTED</code>).</li><li>Displays the app with an <code>UNVERIFIED / LOCAL DEV</code> badge in Control Center and restricts WebSocket origins to <code>127.0.0.1</code> / <code>localhost</code>.</li></ul><h3 id="package-app-source-dir-out-bundle-dir-oci-ref-ref" tabindex="-1"><code>--package-app &lt;source_dir&gt; --out &lt;bundle_dir&gt; [--oci-ref &lt;ref&gt;]</code> <a class="header-anchor" href="#package-app-source-dir-out-bundle-dir-oci-ref-ref" aria-label="Permalink to &quot;`--package-app &lt;source_dir&gt; --out &lt;bundle_dir&gt; [--oci-ref &lt;ref&gt;]`&quot;">​</a></h3><p>Packages a validated worker directory into a standards-compliant <strong>OCI Image Layout v1.0.0</strong> directory and outputs <code>manifest_sha256</code> plus a <code>CatalogAppEntry</code> JSON snippet:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --package-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/my-ocr-worker-oci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oci-ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/your-org/my-ocr-worker:0.1.0</span></span></code></pre></div><p>Automatically strips <code>*.key</code>, <code>*.pem</code>, <code>*.secret</code>, <code>jetpack-root-signing*</code>, <code>.git/</code>, <code>.venv/</code>, and <code>__pycache__/</code> so secrets cannot leak into published layers.</p><h2 id="catalog-operator-commands" tabindex="-1">Catalog Operator Commands <a class="header-anchor" href="#catalog-operator-commands" aria-label="Permalink to &quot;Catalog Operator Commands&quot;">​</a></h2><h3 id="generate-catalog-keypair-out-priv-path" tabindex="-1"><code>--generate-catalog-keypair --out-priv &lt;path&gt;</code> <a class="header-anchor" href="#generate-catalog-keypair-out-priv-path" aria-label="Permalink to &quot;`--generate-catalog-keypair --out-priv &lt;path&gt;`&quot;">​</a></h3><p>Generates an <code>Ed25519</code> root keypair using <code>OsRng</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --generate-catalog-keypair</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out-priv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.secrets/jetpack-root-signing.key</span></span></code></pre></div><ul><li>Writes the 32-byte seed (64 lowercase hex characters) atomically (<code>create_new(true)</code>) with mode <code>0600</code> on Unix.</li><li>Prints only the public key hex and the Rust <code>CATALOG_VERIFY_PUBKEY</code> literal to stdout.</li></ul><h3 id="sign-catalog-catalog-json-path-key-priv-key-path" tabindex="-1"><code>--sign-catalog &lt;catalog_json_path&gt; [--key &lt;priv_key_path&gt;]</code> <a class="header-anchor" href="#sign-catalog-catalog-json-path-key-priv-key-path" aria-label="Permalink to &quot;`--sign-catalog &lt;catalog_json_path&gt; [--key &lt;priv_key_path&gt;]`&quot;">​</a></h3><p>Canonicalizes <code>SignedAppCatalog</code>, signs it with <code>Ed25519</code> (reading <code>--key</code> or <code>JETPACK_SIGNING_KEY</code>), writes <code>ed25519_signature</code> atomically, and immediately re-verifies the file from disk:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sign-catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crates/jetpack-daemon/assets/catalog.signed.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.secrets/jetpack-root-signing.key</span></span></code></pre></div><h2 id="runtime-inspection-diagnostic-flags" tabindex="-1">Runtime, Inspection &amp; Diagnostic Flags <a class="header-anchor" href="#runtime-inspection-diagnostic-flags" aria-label="Permalink to &quot;Runtime, Inspection &amp; Diagnostic Flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--headless</code></td><td style="text-align:left;">Run <code>jetpack-daemon</code> without a desktop system tray icon (CI / server).</td></tr><tr><td style="text-align:left;"><code>--seed-core-apps</code></td><td style="text-align:left;">Package and pre-install curated core workers from <code>examples/</code> (e.g., slim release bundle <code>examples/ffmpeg-media-converter</code>, excluding <code>.venv</code>, <code>__pycache__</code>, <code>tests</code>, and media files) into CAS and <code>&lt;root&gt;/apps/</code>.</td></tr><tr><td style="text-align:left;"><code>--export-diagnostics [--out &lt;path&gt;]</code></td><td style="text-align:left;">Collect a sanitized <code>.zip</code> diagnostic bundle (<code>diagnostics.json</code> + redacted <code>daemon.log</code> tail) and write it to <code>&lt;path&gt;</code> or <code>&lt;root&gt;/logs/jetpack-diagnostics-&lt;timestamp&gt;.zip</code>.</td></tr><tr><td style="text-align:left;"><code>--print-hardware-profile</code></td><td style="text-align:left;">Probe CPU topology, RAM/unified memory, and GPUs (<code>NVML</code>, <code>Vulkan</code>, <code>DX12</code>, <code>Metal</code>).</td></tr><tr><td style="text-align:left;"><code>--list-paired-clients</code></td><td style="text-align:left;">List approved origins and client UUIDs stored in <code>paired_clients.db</code>.</td></tr><tr><td style="text-align:left;"><code>--list-installed-apps</code></td><td style="text-align:left;">Scan <code>&lt;root&gt;/apps/</code> and print discovered manifests and versions.</td></tr><tr><td style="text-align:left;"><code>--register-uri-scheme</code></td><td style="text-align:left;">Register <code>jetpack://</code> and <code>corenode://</code> custom URL schemes in user space.</td></tr><tr><td style="text-align:left;"><code>--generate-test-pair-uri</code></td><td style="text-align:left;">Print a deterministic test <code>jetpack://pair</code> URI and SHA-256 fingerprint.</td></tr><tr><td style="text-align:left;"><code>--test-ws-client</code></td><td style="text-align:left;">Connect to a running daemon (<code>127.0.0.1:9470</code>) to verify PNA, handshake, and <code>system.echo</code> (supports <code>--send-json</code> and <code>--origin</code>).</td></tr><tr><td style="text-align:left;"><code>--ws-smoke-test</code></td><td style="text-align:left;">Run offline end-to-end WebSocket security and <code>hardware.get_profile</code> smoke test.</td></tr><tr><td style="text-align:left;"><code>--oci-smoke-test</code></td><td style="text-align:left;">Run offline OCI CAS, SHA-256 verification, and hardlink/APFS clone smoke test.</td></tr><tr><td style="text-align:left;"><code>--python-smoke-test</code></td><td style="text-align:left;">Run offline hermetic <code>uv</code> + <code>python-build-standalone</code> provisioner smoke test.</td></tr><tr><td style="text-align:left;"><code>--sandbox-smoke-test</code></td><td style="text-align:left;">Run offline OS native kernel sandbox (<code>AppContainer</code> / <code>Seatbelt</code> / <code>bwrap+Landlock</code>) smoke test.</td></tr><tr><td style="text-align:left;"><code>--worker-ipc-smoke-test</code></td><td style="text-align:left;">Run offline sandboxed worker IPC, userspace proxy, and lifecycle cleanup smoke test.</td></tr><tr><td style="text-align:left;"><code>--full-e2e-smoke-test</code></td><td style="text-align:left;">Run the full end-to-end orchestrator, sandbox, GPU worker, and WebSocket integration test.</td></tr></tbody></table>',29)])])}const k=t(s,[["render",d]]);export{g as __pageData,k as default};
